import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./IncomeCategory.css";

function IncomeCategory({ onNext }) {
  const [selectedIncome, setSelectedIncome] = useState("");
  const navigate = useNavigate();

  const handleSelect = (type) => {
    setSelectedIncome(type);
  };

  const handleContinue = () => {
    if (!selectedIncome) {
      alert("Please select an income category");
      return;
    }

    if (onNext) onNext(selectedIncome);
    navigate("/questionnaire");
  };

  const incomeOptions = [
    {
      name: "Fixed Income",
      desc: "Stable salary or pension",
      icon: "💼"
    },
    {
      name: "Variable Income",
      desc: "Income changes monthly",
      icon: "📊"
    },
    {
      name: "Freelancer / Gig",
      desc: "Project-based earnings",
      icon: "🧑‍💻"
    },
    {
      name: "Business Owner",
      desc: "Own business income",
      icon: "🏢"
    },
    {
      name: "No Income",
      desc: "Currently not earning",
      icon: "📉"
    },
    {
      name: "Multiple Sources",
      desc: "More than one income source",
      icon: "🔀"
    }
  ];

  return (
    <div className="income-container">
      <h1 className="income-title">Select Your Income Category</h1>
      <p className="income-subtitle">
        Choose the option that best describes your income source
      </p>

      <div className="income-grid">
        {incomeOptions.map((item) => (
          <div
            key={item.name}
            className="income-card"
            onClick={() => handleSelect(item.name)}
            style={{
              border:
                selectedIncome === item.name
                  ? "2px solid #1e3c72"
                  : "1px solid #dcdcdc"
            }}
          >
            <div className="income-icon">{item.icon}</div>
            <div className="income-name">{item.name}</div>
            <div className="income-desc">{item.desc}</div>
          </div>
        ))}
      </div>

      <button
        onClick={handleContinue}
        style={{
          padding: "12px 30px",
          fontSize: "16px",
          borderRadius: "8px",
          border: "none",
          background: "#ffffff",
          color: "#1e3c72",
          cursor: "pointer"
        }}
      >
        Continue
      </button>
    </div>
  );
}

export default IncomeCategory;
